import sys
input = sys.stdin.read
data = input().split()

s = data[0]
p = data[1]

n = len(s)
m = len(p)

def kmp_table(p):
    table = [0] * (m + 1)
    i = 0
    for j in range(1, m):
        if p[i] == p[j]:
            i += 1
        else:
            i = 0
        table[j + 1] = i
    return table

table = kmp_table(p)

results = []
for x in range(n + 1):
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(m):
            if s[i] == p[j]:
                dp[i + 1][j + 1] = dp[i][j] + 1
            else:
                dp[i + 1][j + 1] = max(dp[i][j + 1], dp[i + 1][j])
    ans = 0
    for i in range(n):
        ans = max(ans, min(i, m * dp[i][m] + (n - i - x)))
    results.append(ans)

for result in results:
    print(result)

